mapper.select:
SELECT o.id, o.price, o.product_amount, o.business_type, o.create_time, o.expected_delivery_time, o.gap, o.category_id, c.category_name, o.status, #{callerId} AS access_user_id, AS private_access, p.public_address AS pick_up_address, r.public_address AS recive_address, IF(, o.product_amount+o.price, NULL) AS runner_receivable, IF(, o.order_number, NULL) AS order_number, IF(, o.service_fee_rate, NULL) AS service_fee_rate, IF(, o.service_fee, NULL) AS service_fee, IF(, o.pay_amount, NULL) AS pay_amount, IF(, o.delivery_time, NULL) AS delivery_time, IF(, o.cancel_time, NULL) AS cancel_time, IF(, o.cancel_reson, NULL) AS cancel_reson, IF(, o.exceed_time, NULL) AS exceed_time, o.door_access, o.user_id, sender.username AS username, IF(, o.phone, NULL) AS phone, o.note, IF(, o.deleted, NULL) AS deleted FROM tb_orders o LEFT JOIN tb_user sender ON sender.id = o.user_id JOIN tb_category c ON c.id=o.category_id JOIN tb_order_address_snapshot p ON p.order_id=o.id AND p.role='PICKUP' AND p.school_id=#{schoolId} JOIN tb_order_address_snapshot r ON r.order_id=o.id AND r.role='RECEIVE' AND r.school_id=#{schoolId} LEFT JOIN tb_take_orders access_take ON access_take.id = ( SELECT MAX(access_candidate.id) FROM tb_take_orders access_candidate WHERE access_candidate.order_id=o.id AND access_candidate.user_id=#{callerId} AND access_candidate.deleted=0 AND access_candidate.status IN (0,1,2)) WHERE o.deleted=0 AND o.status=0 AND p.compus_id = #{pickup.compusId} AND p.build_category_id = #{pickup.buildCategoryId} AND p.building_id = #{pickup.buildingId} AND r.compus_id = #{receive.compusId} AND r.build_category_id = #{receive.buildCategoryId} AND r.building_id = #{receive.buildingId} AND o.category_id=#{query.categoryId}
AND (BINARY LOWER(COALESCE(o.note,'')) LIKE BINARY CONCAT('%',#{query.literalKeyword},'%') ESCAPE '!' OR BINARY LOWER(COALESCE(c.category_name,'')) LIKE BINARY CONCAT('%',#{query.literalKeyword},'%') ESCAPE '!' OR BINARY LOWER(COALESCE(p.public_address,'')) LIKE BINARY CONCAT('%',#{query.literalKeyword},'%') ESCAPE '!' OR BINARY LOWER(COALESCE(r.public_address,'')) LIKE BINARY CONCAT('%',#{query.literalKeyword},'%') ESCAPE '!')
ORDER BY
COALESCE(o.price,0) desc, COALESCE(o.price,0) asc,
o.create_time asc, o.id asc o.create_time desc, o.id desc
LIMIT #{query.limit} OFFSET #{query.offset}

AND orders.status = -1 AND orders.status = 0 AND orders.status IN (1,2,3) AND orders.status IN (5,6,7) AND orders.status = 4 AND orders.status IN (-2,-3,-4)
AND BINARY LOWER( REPLACE( CONCAT(COALESCE(category.category_name,''), COALESCE(orders.note,''), IF(LOCATE(' ',address_pick_up.address)>0,SUBSTRING(address_pick_up.address,LOCATE(' ',address_pick_up.address)+1),''), IF(LOCATE(' ',address_recive.address)>0,SUBSTRING(address_recive.address,LOCATE(' ',address_recive.address)+1),''), CASE WHEN orders.business_type='PURCHASE' AND orders.status=1 THEN '采购中' WHEN orders.business_type='PURCHASE' AND orders.status=2 THEN '配送中' ELSE CASE orders.status WHEN -4 THEN '退款异常' WHEN -3 THEN '退款成功' WHEN -2 THEN '退款中' WHEN -1 THEN '待支付' WHEN 0 THEN '待接单' WHEN 1 THEN '已接单' WHEN 2 THEN '配送中' WHEN 3 THEN '已送达' WHEN 4 THEN '已取消' WHEN 5 THEN '已完成' WHEN 6 THEN '提现成功' WHEN 7 THEN '提现失败' ELSE '订单状态' END END, COALESCE(orders.order_number,''), COALESCE(DATE_FORMAT(orders.create_time,'%Y-%m-%d %H:%i:%s'),''), CAST(CAST(COALESCE(orders.pay_amount,0) AS DECIMAL(20,2)) AS CHAR)) , #{space}, '') ) LIKE BINARY CONCAT('%', #{query.searchKeyword}, '%') ESCAPE '!'
ORDER BY orders.create_time desc, orders.id desc LIMIT #{query.limit} OFFSET #{query.offset}

-- 这里查找出来的字段为OrderShowVO字段，别名为了能够匹配上 SELECT orders.id, address_pick_up.address AS pick_up_address, -- 取件地址，字符串，类似：浙大城市学院 南校区 弘毅楼 寝室楼下 address_recive.address AS recive_address, -- 收件地址，字符串，类似：浙大城市学院 南校区 弘毅楼 寝室楼下 orders.order_number, orders.price, orders.product_amount, orders.business_type, (orders.product_amount + orders.price) AS runner_receivable, orders.service_fee_rate, orders.service_fee, orders.pay_amount, orders.expected_delivery_time, orders.delivery_time, orders.cancel_time , orders.cancel_reson, orders.exceed_time, orders.gap, orders.create_time, orders.door_access, orders.user_id, orders.username, orders.phone, orders.status, orders.note, orders.category_id, category.category_name, orders.deleted FROM tb_orders AS orders, -- 这是订单表 主表 tb_category AS category,
(SELECT order_id AS id, address FROM tb_order_address_snapshot WHERE role = 'PICKUP'
and order_id in
#{id}
) AS address_pick_up,
(SELECT order_id AS id, address FROM tb_order_address_snapshot WHERE role = 'RECEIVE'
and order_id in
#{id}
) AS address_recive
WHERE orders.deleted = 0 AND orders.status = 0 AND orders.category_id = category.id AND orders.id = address_pick_up.id AND orders.id = address_recive.id
ORDER BY orders.create_time desc LIMIT 20

select status
from tb_orders
where deleted = 0 AND id = #{id}

select * from tb_orders
where deleted = 0 AND
      order_number = #{orderNumber}

mapper.update:
update tb_orders
pick_up_address = #{pickUpAddress}, recive_address = #{reciveAddress}, order_number = #{orderNumber}, price = #{price}, product_amount = #{productAmount}, business_type = #{businessType}, service_fee_rate = #{serviceFeeRate}, service_fee = #{serviceFee}, pay_amount = #{payAmount}, delivery_time = #{deliveryTime}, cancel_time = #{cancelTime}, cancel_reson = #{cancelReson}, exceed_time = #{exceedTime}, gap = #{gap}, create_time = #{createTime}, door_access = #{doorAccess}, user_id = #{userId}, username = #{username}, phone = #{phone}, status = #{status}, note = #{note}, category_id = #{categoryId}, deleted = #{deleted},
where id = #{id}

update tb_orders
set status = #{status}
where order_number = #{orderNumber}

    and status = -1
    and status in (-1, 0, 4, -2, -4)
    and status in (-2, -4)
    and status in (5, 7)
    and status = #{status}

mapper.select:
SELECT COUNT(*) FROM tb_orders o WHERE o.deleted = 0
AND o.status IN
#{status}

SELECT o.id, o.order_number, o.status, c.category_name, o.price, o.product_amount, o.business_type, (o.product_amount + o.price) AS runner_receivable, o.service_fee, o.pay_amount, o.username, o.phone, o.note, o.door_access, o.create_time, ap.address AS pick_up_address, ar.address AS recive_address, ri.refund / 100.0 AS refund_amount, ri.refund_status FROM tb_orders o LEFT JOIN tb_category c ON o.category_id = c.id LEFT JOIN tb_order_address_snapshot ap ON o.id = ap.order_id AND ap.role = 'PICKUP' LEFT JOIN tb_order_address_snapshot ar ON o.id = ar.order_id AND ar.role = 'RECEIVE'
WHERE o.deleted = 0
ORDER BY o.create_time DESC, o.id DESC LIMIT #{offset}, #{limit}

SELECT o.id, o.order_number, o.status, c.category_name, o.price, o.product_amount, o.business_type, (o.product_amount + o.price) AS runner_receivable, o.service_fee, o.pay_amount, o.username, o.phone, o.note, o.door_access, o.create_time, o.cancel_time, o.cancel_reson AS cancel_reason, o.delivery_time, ap.address AS pick_up_address, ar.address AS recive_address, tk_user.realname AS taker_name, tk_user.phone AS taker_phone, tk.create_time AS take_order_time, ri.refund / 100.0 AS refund_amount, ri.refund_status FROM tb_orders o LEFT JOIN tb_category c ON o.category_id = c.id LEFT JOIN tb_order_address_snapshot ap ON o.id = ap.order_id AND ap.role = 'PICKUP' LEFT JOIN tb_order_address_snapshot ar ON o.id = ar.order_id AND ar.role = 'RECEIVE' LEFT JOIN tb_take_orders tk ON o.id = tk.order_id AND tk.deleted = 0 LEFT JOIN tb_user tk_user ON tk.user_id = tk_user.id
WHERE o.deleted = 0 AND o.status IN
#{s}
ORDER BY o.create_time DESC, o.id DESC LIMIT #{offset}, #{limit}

SELECT COALESCE(SUM(pay_amount), 0) FROM tb_orders
WHERE deleted = 0 AND pay_amount > 0
  AND create_time >= #{startTime} AND create_time <= #{endTime}

SELECT COALESCE(SUM(service_fee), 0) FROM tb_orders
WHERE deleted = 0 AND service_fee > 0
  AND create_time >= #{startTime} AND create_time <= #{endTime}
